/* Listen Up! Speak Out! — service worker (generated by tools/app/build_www.py; do not edit sw.js by hand)
   App files are saved when the app is installed; audio is saved on first play
   or when a whole grade is downloaded from the Home page. */
const V = '__VERSION__', AV = '__AUDIO_VERSION__';
const SHELL = 'lsp-shell-' + V, AUDIO = 'lsp-audio-' + AV;
const FILES = __SHELL_FILES__;

self.addEventListener('install', e => {
  e.waitUntil(caches.open(SHELL).then(c => c.addAll(FILES.map(f => new Request(f, { cache: 'reload' })))));
});
self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    for (const k of await caches.keys()) if (k.startsWith('lsp-') && k !== SHELL && k !== AUDIO) await caches.delete(k);
    await self.clients.claim();
  })());
});
self.addEventListener('message', e => { if (e.data === 'skipWaiting') self.skipWaiting(); });

self.addEventListener('fetch', e => {
  const r = e.request;
  if (r.method !== 'GET') return;
  const u = new URL(r.url);
  if (u.origin !== location.origin) return;
  if (u.pathname.endsWith('.mp3')) { e.respondWith(audio(r)); return; }
  e.respondWith(shell(r));
});

async function shell(r) {
  const c = await caches.open(SHELL);
  if (r.mode === 'navigate') {   // same saved version of every file until the user presses Update
    const page = await c.match('index.html');
    if (page) return page;
    try { return await fetch(r); } catch (e) { return Response.error(); }
  }
  const hit = await c.match(r, { ignoreSearch: true });
  if (hit) return hit;
  try { return await fetch(r); } catch (e) { return Response.error(); }
}

/* Audio: cache first. Safari asks for byte ranges, so ranges are cut from the saved file. */
async function audio(r) {
  const c = await caches.open(AUDIO);
  let res = await c.match(r.url);
  if (!res) {
    try { res = await fetch(r.url); } catch (e) { return new Response('', { status: 504, statusText: 'Offline' }); }
    if (res.status === 200) { try { await c.put(r.url, res.clone()); } catch (e) {} }
  }
  const range = r.headers.get('range');
  if (!range || res.status !== 200) return res;
  const buf = await res.arrayBuffer(), size = buf.byteLength;
  const m = /bytes=(\d*)-(\d*)/.exec(range);
  let a = 0, b = size - 1;
  if (m) {
    if (m[1] === '' && m[2] !== '') { a = Math.max(0, size - +m[2]); }
    else { a = +m[1] || 0; if (m[2] !== '') b = Math.min(+m[2], size - 1); }
  }
  if (a >= size) return new Response('', { status: 416, headers: { 'Content-Range': `bytes */${size}` } });
  return new Response(buf.slice(a, b + 1), { status: 206, statusText: 'Partial Content', headers: {
    'Content-Type': 'audio/mpeg', 'Content-Range': `bytes ${a}-${b}/${size}`, 'Content-Length': String(b - a + 1), 'Accept-Ranges': 'bytes' } });
}
